internal class GUPPricingObjectQueryBuilder
{
    private GUPPricingAttributeSource querySourceType;
    private Query query;
    private Map queryBuildDatasourceMap;
    private QueryBuildDataSource rootDS;
    private List queryBuilderNodes;
    private boolean useProductVariants;
    private boolean keepProductRoot;

}

Method.Source:
public static GUPPricingObjectQueryBuilder constructFromPricingRule(
    GUPPricingRule  _pricingRule,
    RefRecId        _modifiedRuleConditionId = 0,
    anytype         _modifiedRuleConditionValue = '',
    boolean         _keepProductRoot = false)
{
    GUPPricingAttributeSource       source;
    GUPPricingObjectQueryBuilder    builder;

    if (_pricingRule.getSourceLevel() == GUPPricingAttributeSourceLevel::Header)
    {
        source = GUPPricingAttributeSource::Customer;
    }
    else
    {
        source = GUPPricingAttributeSource::Product;
    }

    builder = new GUPPricingObjectQueryBuilder(source);
    builder.parmKeepProductRoot(_keepProductRoot);

    GUPPricingAttributeLink attrLink;
    GUPPricingAttributeLink attrLink1;
    GUPPricingRuleCondition ruleCond;
    GUPPricingAttributeGroup attributeGroup;

    while select ruleCond
        where ruleCond.RuleId == _pricingRule.RecId
        join attrLink
        where attrLink.RecId == ruleCond.ConditionAttribute
        outer join attributeGroup
            where ((ruleCond.RecId == _modifiedRuleConditionId && attributeGroup.Name == _modifiedRuleConditionValue)
                    || (ruleCond.RecId != _modifiedRuleConditionId && attributeGroup.Name == ruleCond.ConditionValue))
                && (attrLink.Source == GUPPricingAttributeSource::CustomerPriceGroup
                    ||  attrLink.Source == GUPPricingAttributeSource::ProductPriceGroup)
        outer join attrLink1
            where attrLink1.PriceAttributeGroupName == attributeGroup.Name
    {
        if(!attrLink1)
        {
            if (ruleCond.RecId == _modifiedRuleConditionId)
            {
                builder.addPricingAttributeFilter(ruleCond.pricingAttribute(), _modifiedRuleConditionValue);
            }
            else
            {
                builder.addPricingAttributeFilter(ruleCond.pricingAttribute(), ruleCond.ConditionValue);
            }
        }
        else
        {
            builder.addPricingAttributeFilter(attrLink1.pricingAttribute(), attrLink1.DefaultValue);
        }
    }      
    return builder;
}

/// <summary>
/// Create <c>GUPPricingObjectQueryBuilder</c> instance for Pricing attribute group
/// </summary>
/// <param name = "_pricingGroup">Pricing group</param>
/// <param name = "_keepProductRoot">Keep root table for product query</param>
/// <returns>Class instance</returns>
public static GUPPricingObjectQueryBuilder constructFromPricingGroup(GUPPricingAttributeGroup _pricingGroup, boolean _keepProductRoot = false)
{
    GUPPricingAttributeSource source;

    if (_pricingGroup.GroupType == GUPPricingAttributeGroupType::Customer)
    {
        source = GUPPricingAttributeSource::Customer;
    }
    else
    {
        source = GUPPricingAttributeSource::Product;
    }

    GUPPricingObjectQueryBuilder builder = new GUPPricingObjectQueryBuilder(source);
    builder.parmKeepProductRoot(_keepProductRoot);

    GUPPricingAttributeLink pricingAttributeLink;

    while select pricingAttributeLink
        where pricingAttributeLink.PriceAttributeGroupName == _pricingGroup.Name
    {
        GUPIPricingAttribute pricingAttr = pricingAttributeLink.pricingAttribute();
        builder.addPricingAttributeFilter(pricingAttr, pricingAttributeLink.DefaultValue);
    }

    return builder;
}

public void new(GUPPricingAttributeSource _source)
{
    this.querySourceType = _source;
    this.query = new Query();
    this.queryBuildDatasourceMap = new Map(Types::String, Types::Class);

    this.queryBuilderNodes = new List(Types::Class);

    this.useProductVariants = false;
}

private void initRootDatasource()
{
    switch (this.querySourceType)
    {
        case GUPPricingAttributeSource::Customer:
            rootDS = query.addDataSource(tableNum(CustTable));
            queryBuildDatasourceMap.insert(tableStr(CustTable), rootDS);
            break;
        case GUPPricingAttributeSource::Product:
            rootDS = query.addDataSource(tableNum(InventTable));
            queryBuildDatasourceMap.insert(tableStr(InventTable), rootDS);
            break;
        case GUPPricingAttributeSource::SalesTable:
            rootDS = query.addDataSource(tableNum(SalesTable));
            queryBuildDatasourceMap.insert(tableStr(SalesTable), rootDS);
            break;
        case GUPPricingAttributeSource::SalesLine:
            rootDS = query.addDataSource(tableNum(SalesLine));
            queryBuildDatasourceMap.insert(tableStr(SalesLine), rootDS);
            break;
        default:
            throw error("@GlobalUnifiedPricing:GUPErrorForUnsupportedPricingAttributeSourceType");
    }
}

public Query build()
{
    this.initRootDatasource();

    List queryBuilderNodesVariant = new List(Types::Class);
    ListEnumerator nodeEnumerator = this.queryBuilderNodes.getEnumerator();
    GUPPricingObjectQueryBuilderNode node;
    GUPIPricingAttribute pricingAttribute;
    GUPPricingAttributeSource source;

    while (nodeEnumerator.moveNext())
    {
        node = nodeEnumerator.current();
        pricingAttribute = node.pricingAttribute;
        source = GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
            pricingAttribute,
            attributeStr(GUPPricingAttributeSourceDiscoveryAttribute)).parmSource();

        if (pricingAttribute is GUPIPricingAttributeEcoResProductVariantDimensionValue && this.useProductVariants)
        {
            queryBuilderNodesVariant.addEnd(node);
            continue;
        }

        pricingAttribute.buildPricingObjectQuery(this.query, node.value, this.queryBuildDatasourceMap);
    }

    if (this.querySourceType == GUPPricingAttributeSource::Product
        && this.useProductVariants)
    {
        QueryBuildDataSource qbdsVariant;

        if (keepProductRoot)
        {
            qbdsVariant = this.addProductVariantDataSource();
        }
        else
        {                
            qbdsVariant = this.buildProductVariantQuery();
        }

        nodeEnumerator = queryBuilderNodesVariant.getEnumerator();
        GUPIPricingAttributeEcoResProductVariantDimensionValue productVariantAttr;

        while (nodeEnumerator.moveNext())
        {
            node = nodeEnumerator.current();
            productVariantAttr = node.pricingAttribute;
            if (productVariantAttr)
            {
                productVariantAttr.buildEcoResProductVariantQuery(this.query, node.value, qbdsVariant);
            }
        }
    }

    return this.query;
}

protected QueryBuildDataSource buildProductVariantQuery()
{
    Query queryVariants = new Query();
    QueryBuildDataSource qbdsVariant = queryVariants.addDataSource(tableNum(EcoResDistinctProductVariant));
    QueryBuildDataSource qbdsInventTable = qbdsVariant.addDataSource(tableNum(InventTable));
    SysQuery::copyDataSource(this.rootDS, qbdsInventTable, true);
    qbdsInventTable.addLink(fieldNum(EcoResDistinctProductVariant, ProductMaster), fieldNum(InventTable, Product));
    qbdsInventTable.joinMode(JoinMode::ExistsJoin);
    this.rootDS = qbdsVariant;

    this.query = queryVariants;

    return qbdsVariant;
}

/// <summary>
/// Add product variants data source
/// </summary>
/// <returns>Product variants data source</returns>
protected QueryBuildDataSource addProductVariantDataSource()
{
    QueryBuildDataSource qbdsInventDimCombination = rootDS.addDataSource(tableNum(InventDimCombination));

    qbdsInventDimCombination.addLink(fieldNum(InventTable, ItemId), fieldNum(InventDimCombination, ItemId));
    qbdsInventDimCombination.joinMode(JoinMode::InnerJoin);

    QueryBuildDataSource qbdsVariant = qbdsInventDimCombination.addDataSource(tableNum(EcoResDistinctProductVariant));

    qbdsVariant.relations(true);
    qbdsVariant.joinMode(JoinMode::InnerJoin);

    return qbdsVariant;
}

public GUPPricingObjectQueryBuilder addPricingAttributeFilter(GUPIPricingAttribute _pricingAttr, anytype _value)
{
    // if _pricingAttr source type mismatch, skip apply filter (or throw error?)
    GUPPricingAttributeSource source =
        GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
            _pricingAttr,
            attributeStr(GUPPricingAttributeSourceDiscoveryAttribute)).parmSource();
    GUPPricingObjectQueryBuilderNode node;

    if (source == this.querySourceType && _value)
    {
        node = new GUPPricingObjectQueryBuilderNode(_pricingAttr, _value);
        queryBuilderNodes.addEnd(node);
    }

    return this;
}

public GUPPricingObjectQueryBuilder addPricingRuleFilter(GUPPricingRule _rule)
{
    GUPPricingRuleCondition ruleCond;

    while select ruleCond where ruleCond.RuleId == _rule.RecId
    {
        this.addPricingAttributeFilter(ruleCond.pricingAttribute(), ruleCond.ConditionValue);
    }

    // TODO: conside rule exclusion.
    return this;
}

public GUPPricingObjectQueryBuilder addProductVariants()
{
    if (this.querySourceType != GUPPricingAttributeSource::Product)
    {
        throw error("@GlobalUnifiedPricing:GUPErrorForUnsupportedPricingAttributeSourceType");
    }

    this.useProductVariants = true;

    return this;
}

public boolean parmKeepProductRoot(boolean _keepProductRoot = keepProductRoot)
{
    keepProductRoot = _keepProductRoot;

    return keepProductRoot;
}
